 auto changed=legacy;changed.consents.find(consent.value)->source.relation_fact_id="family_collateral:9";check(!bind_collateral_control_result_in_candidate(f.c,legacy,changed,f.policies,f.state,f.state,"first",2,*result).ok,"old consent cannot be altered through unrelated commit");
 BiologicalControlCatalog bio;BiologicalControlState bs;check(!bind_biological_control_result_in_candidate(f.c,legacy,legacy,bio,bs,bs,"first",2,*result).ok,"old biological format refuses unrelated collateral bytes");check(bind_biological_control_result_in_candidate(f.c,legacy,legacy,bio,bs,bs,"first",2,*result,FamilyLegacyVersion::collateral3).ok,"explicit Legacy3 preserves biological binder on mixed state");DiscipleControlCatalog disc;DiscipleControlState ds;check(!bind_disciple_control_result_in_candidate(f.c,legacy,legacy,disc,ds,ds,"first",2,*result).ok,"old disciple format refuses unrelated new bytes");check(bind_disciple_control_result_in_candidate(f.c,legacy,legacy,disc,ds,ds,"first",2,*result,FamilyLegacyVersion::collateral3).ok,"explicit Legacy3 preserves disciple binder on mixed state");
 const auto permanent=f.state;f.c.state().history.clear();f.c.state().results={};check(validate_collateral_control_result_bindings(f.c,legacy,f.policies,f.state).ok,"cache pruning preserves both permanent results");auto reused=std::make_shared<CommitResult>(*result);reused->result_id=f.c.next_id("result").value;reused->revision=++f.c.state().identity.revision;f.c.state().request_sequences.set("first",3);f.c.state().results.set("first:3",reused);check(!validate_collateral_control_result_bindings(f.c,legacy,f.policies,f.state).ok,"first retained same-tick result cannot reattach old consent");f.c.state().results={};
